    /**
     * Tests getting all ReturnItems.
     *
     * @return    Collection
     */
    public List<ReturnItem> testGetAll() throws Throwable {
    LOGGER.info( "ReturnItemTest:testGetAll() - Retrieving Collection of ReturnItems:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ReturnItem : " );
    List<ReturnItem> collection  = null;

    try {
        // call the static get method on the ReturnItemService
        collection = service.getAllReturnItem();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ReturnItem currEntity  = null;
            Iterator<ReturnItem> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getReturnItemId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

